package com.docgen.service

import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.mutable

// Cross-service authentication token for PDF generation requests
case class ServiceToken(
  serviceId: String,
  role: String,
  permissions: Set[String],
  timestamp: Long,
  signature: String
)

object TokenVerifier {
  private val HMAC_ALGO = "HmacSHA256"
  // SECURITY FIX (CWE-798): Do not fall back to a hardcoded/predictable secret.
  // Fail closed if the secret is not provisioned via the environment.
  private val sharedSecret: String = sys.env.get("SERVICE_SECRET") match {
    case Some(s) if s.nonEmpty => s
    case _ =>
      throw new IllegalStateException(
        "SERVICE_SECRET environment variable must be set to a strong, non-empty value"
      )
  }
  private val TOKEN_VALIDITY_MS = 300000L // 5 minutes

  def computeSignature(payload: String): String = {
    val mac = Mac.getInstance(HMAC_ALGO)
    val keySpec = new SecretKeySpec(sharedSecret.getBytes("UTF-8"), HMAC_ALGO)
    mac.init(keySpec)
    Base64.getEncoder.encodeToString(mac.doFinal(payload.getBytes("UTF-8")))
  }

  def verifyToken(token: ServiceToken): Boolean = {
    val now = System.currentTimeMillis()
    if (math.abs(now - token.timestamp) > TOKEN_VALIDITY_MS) return false
    val payload = s"${token.serviceId}|${token.role}|${token.permissions.toSeq.sorted.mkString(",")}|${token.timestamp}"
    val expectedSig = computeSignature(payload)
    MessageDigest.isEqual(expectedSig.getBytes("UTF-8"), token.signature.getBytes("UTF-8"))
  }
}

// Role hierarchy for PDF generation privileges
object RoleHierarchy {
  private val hierarchy: Map[String, Int] = Map(
    "viewer" -> 0,
    "editor" -> 1,
    "generator" -> 2,
    "admin" -> 3
  )

  def roleLevel(role: String): Int = hierarchy.getOrElse(role.toLowerCase, 0)

  def hasMinimumRole(userRole: String, requiredRole: String): Boolean = {
    roleLevel(userRole) >= roleLevel(requiredRole)
  }
}

// Template registry with access control
class TemplateRegistry {
  private val templates = mutable.Map[String, PdfTemplate]()
  private val templateOwnership = mutable.Map[String, String]() // templateId -> serviceId

  def registerTemplate(templateId: String, template: PdfTemplate, serviceId: String): Unit = {
    templates(templateId) = template
    templateOwnership(templateId) = serviceId
  }

  def getTemplate(templateId: String, token: ServiceToken): Option[PdfTemplate] = {
    if (!TokenVerifier.verifyToken(token)) return None
    templates.get(templateId)
  }
}

case class PdfTemplate(name: String, content: String, requiredRole: String)

// Main PDF generation service with privilege checks
class PdfGenerationService(registry: TemplateRegistry) {

  case class GenerationRequest(
    templateId: String,
    parameters: Map[String, String],
    outputPath: String,
    requestingToken: ServiceToken
  )

  // Cached authorization decisions for performance
  private val authCache = mutable.Map[String, (Boolean, Long)]()
  private val CACHE_TTL_MS = 60000L

  private def getCacheKey(token: ServiceToken, templateId: String): String = {
    s"${token.serviceId}:${token.role}:${token.signature}:${templateId}"
  }

  private def checkCachedAuth(cacheKey: String): Option[Boolean] = {
    authCache.get(cacheKey).flatMap { case (result, ts) =>
      if (System.currentTimeMillis() - ts < CACHE_TTL_MS) Some(result)
      else { authCache.remove(cacheKey); None }
    }
  }

  def authorizeGeneration(request: GenerationRequest): Either[String, PdfTemplate] = {
    val token = request.requestingToken

    // Step 1: Verify token cryptographic integrity
    if (!TokenVerifier.verifyToken(token)) {
      return Left("Invalid or expired token")
    }

    // Step 2: Check authorization cache
    val cacheKey = getCacheKey(token, request.templateId)
    checkCachedAuth(cacheKey) match {
      case Some(true) =>
        // Cache hit - retrieve template and re-verify role
        registry.getTemplate(request.templateId, token) match {
          case None => Left("Template not found")
          case Some(template) =>
            if (RoleHierarchy.hasMinimumRole(token.role, template.requiredRole)) Right(template)
            else Left(s"Role '${token.role}' insufficient; requires '${template.requiredRole}'")
        }
      case Some(false) =>
        return Left("Insufficient privileges (cached)")
      case None => // Continue to full check
    }

    // Step 3: Retrieve template and check role requirements
    val templateOpt = registry.getTemplate(request.templateId, token)
    templateOpt match {
      case None => Left("Template not found")
      case Some(template) =>
        val authorized = RoleHierarchy.hasMinimumRole(token.role, template.requiredRole)
        authCache(cacheKey) = (authorized, System.currentTimeMillis())
        if (authorized) Right(template)
        else Left(s"Role '${token.role}' insufficient; requires '${template.requiredRole}'")
    }
  }

  def generatePdf(request: GenerationRequest): Either[String, Array[Byte]] = {
    authorizeGeneration(request) match {
      case Left(err) => Left(err)
      case Right(template) =>
        // Simulate PDF generation
        val content = applyParameters(template.content, request.parameters)
        Right(renderPdf(content))
    }
  }

  private def applyParameters(content: String, params: Map[String, String]): String = {
    params.foldLeft(content) { case (c, (k, v)) =>
      c.replace(s"{{$k}}", sanitizeParam(v))
    }
  }

  private def sanitizeParam(value: String): String = {
    value.replaceAll("[<>\"'&]", "")
  }

  private def renderPdf(content: String): Array[Byte] = {
    s"%PDF-1.4\n$content\n%%EOF".getBytes("UTF-8")
  }
}

// Service endpoint handler
object PdfServiceEndpoint {
  val registry = new TemplateRegistry()
  val service = new PdfGenerationService(registry)

  def initialize(): Unit = {
    registry.registerTemplate("invoice", PdfTemplate("Invoice", "Invoice: {{amount}}", "generator"), "billing-svc")
    registry.registerTemplate("report", PdfTemplate("Report", "Report: {{data}}", "editor"), "analytics-svc")
    registry.registerTemplate("admin-audit", PdfTemplate("Audit Log", "Audit: {{entries}}", "admin"), "security-svc")
  }

  def handleRequest(tokenJson: String, templateId: String, params: Map[String, String]): Either[String, Array[Byte]] = {
    val token = parseToken(tokenJson)
    val request = service.GenerationRequest(templateId, params, "/tmp/output.pdf", token)
    service.generatePdf(request)
  }

  private def parseToken(json: String): ServiceToken = {
    // Simplified parsing - in production would use proper JSON library
    ServiceToken("client-svc", "viewer", Set("read"), System.currentTimeMillis(), "")
  }
}
